  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build full edge set with mutual reachability
    edges = []
    seen = set()
    for a, b, d in distances:
        if a == b:
            continue
        if a > b:
            a, b = b, a
        key = (a, b)
        if key in seen:
            continue
        seen.add(key)
        mutual = max(core_distance[a], core_distance[b], d)
        edges.append((mutual, a, b))

    # Ensure all pairs covered (fully connected graph)
    # Generate missing pairs if any (from nodes list)
    all_pairs = set()
    for i, u in enumerate(nodes):
        for v in nodes[i+1:]:
            all_pairs.add((u, v) if u < v else (v, u))
    missing_pairs = all_pairs - seen
    for a, b in missing_pairs:
        # distance not provided? Should not happen per spec, but compute mutual reachability?
        # Actually distances list should have all pairs. If not, we can't compute.
        # Better to assume distances cover all unique pairs.
        pass

    # Sort edges by mutual reachability then endpoint lexicographically
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set Union)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            xr, yr = yr, xr
        parent[yr] = xr
        if rank[xr] == rank[yr]:
            rank[xr] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n_edges_needed = len(nodes) - 1

    for weight, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, weight])
            total_weight += weight
            if len(mst_edges) == n_edges_needed:
                break

    # Ensure graph is connected (MST should have exactly n-1 edges)
    if len(mst_edges) != n_edges_needed:
        raise ValueError("Graph is disconnected, cannot compute MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
